import sys
from collections import defaultdict

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    count = 0
    prefix_ones = [0] * (n + 1)

    for i in range(n):
        prefix_ones[i + 1] = prefix_ones[i] + (s[i] == '1')

    for l in range(n):
        for r in range(l + 1, n + 1):
            num_ones = prefix_ones[r] - prefix_ones[l]
            if num_ones > 0 and (r - l) % num_ones == 0:
                count += 1

    print(count)

main()
